begin;
create extension if not exists pgtap with schema extensions;
select plan(15);
delete from public.team_members;
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000201','direct.designer@example.test');
insert into public.team_members(id,auth_user_id,email,display_name) values('00000000-0000-4000-8000-000000000202','00000000-0000-4000-8000-000000000201','direct.designer@example.test','Diseño');
insert into public.team_member_roles(member_id,role) values('00000000-0000-4000-8000-000000000202','designer');
set local role authenticated;
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000201';
select public.save_customer('00000000-0000-4000-8000-000000000203',null,'{"display_name":"Cliente directo","cuit":"20-12345678-9"}');
select lives_ok($$select public.create_direct_order('00000000-0000-4000-8000-000000000204','00000000-0000-4000-8000-000000000203',null,null,'Nota interna','[{"description":"Folletos","quantity":500,"amount":"123.45"},{"description":"Tarjetas","quantity":100,"amount":"200"}]')$$,'Se crea una nota sin presupuesto');
select ok((select quote_id is null and quote_version_id is null from public.orders where id='00000000-0000-4000-8000-000000000204'),'No se inventa un origen');
select is((select total from public.orders where id='00000000-0000-4000-8000-000000000204'),323.45::numeric,'Se suman importes de lote sin multiplicar por cantidades');
select is((select count(*) from public.order_items where order_id='00000000-0000-4000-8000-000000000204' and production_status='pending'),2::bigint,'Todos los productos empiezan pendientes');
select is((select customer_snapshot->>'cuit' from public.orders where id='00000000-0000-4000-8000-000000000204'),'20123456789','La instantánea incluye CUIT');
select public.save_customer('00000000-0000-4000-8000-000000000203',1,'{"display_name":"Nombre cambiado"}');
select is((select customer_snapshot->>'display_name' from public.orders where id='00000000-0000-4000-8000-000000000204'),'Cliente directo','La nota conserva los datos acordados');
select lives_ok($$select public.create_direct_order('00000000-0000-4000-8000-000000000204',null,null,null,'','[]')$$,'El reintento devuelve la nota existente');
select is((select count(*) from public.order_items where order_id='00000000-0000-4000-8000-000000000204'),2::bigint,'El reintento no duplica productos');
select throws_ok($$select public.create_direct_order('00000000-0000-4000-8000-000000000205','00000000-0000-4000-8000-000000000299',null,null,'','[{"description":"Producto","quantity":1,"amount":"100"}]')$$,'P0002',null,'No admite cliente inexistente');
select throws_ok($$select public.create_direct_order('00000000-0000-4000-8000-000000000205','00000000-0000-4000-8000-000000000203',null,null,'','[]')$$,'22023',null,'No admite notas vacías');
select throws_ok($$select public.create_direct_order('00000000-0000-4000-8000-000000000205',null,'{"display_name":"No debe guardarse"}','00000000-0000-4000-8000-000000000206','','[{"description":"Producto","quantity":0,"amount":"100"}]')$$,'22023',null,'Valida cantidades también en la base');
select is((select count(*) from public.customers where id='00000000-0000-4000-8000-000000000206'),0::bigint,'Un pedido inválido no deja una ficha huérfana');
select lives_ok($$select public.create_direct_order('00000000-0000-4000-8000-000000000205',null,'{"display_name":"Cliente nuevo","cuit":"20123456789"}','00000000-0000-4000-8000-000000000206','','[{"description":"Producto","quantity":1,"amount":"100"}]')$$,'Permite crear ficha y nota juntas');
select ok(not has_function_privilege('anon','public.create_direct_order(uuid,uuid,jsonb,uuid,text,jsonb,jsonb,uuid,uuid,text,jsonb)','EXECUTE'),'El público no puede crear notas');
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000299';
select throws_ok($$select public.create_direct_order('00000000-0000-4000-8000-000000000207',null,null,null,'','[]')$$,'42501',null,'Una cuenta sin Diseño no puede crear notas');
reset role;
select * from finish();
rollback;
